public Yaf_View_InterfacenullfalseYaf_Dispatcher::initView stringtemplates_dir arraynulloptionsnull
Inicializa y devuelve una instancia de Yaf_View_Simple asociada al despachador, usando el directorio de plantillas indicado.

  &reftitle.examples;

   Ejemplo de Yaf_Dispatcher::initView


<?php
$app = new Yaf_Application(dirname(__FILE__) . "/conf/application.ini");

$view = Yaf_Dispatcher::getInstance()->initView(
    dirname(__FILE__) . "/application/views",
    array("tpl_suffix" => ".html")
);

$view->assign("title", "Home");
?>
